SELECT COALESCE(sub0.time, sub1.time, sub2.time) AS "time", (sub0.value) AS "sensor.ENERGY.Total", (sub1.value) AS "sensor.ENERGY.Total", (sub2.value) AS "sensor.ENERGY.Total" FROM (SELECT time_bucket('1h', "time", 'Europe/Berlin') AS "time", avg("sensor.ENERGY.Total") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" > now() - interval '1d' GROUP BY 1 ORDER BY 1 ASC) sub0 FULL OUTER JOIN (SELECT time_bucket('1h', "time", 'Europe/Berlin') AS "time", last("sensor.ENERGY.Total", "time") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" > now() - interval '1d' GROUP BY 1 ORDER BY 1 DESC) sub1 on sub0.time = sub1.time FULL OUTER JOIN (SELECT time_bucket('1h', "time", 'Europe/Berlin') AS "time", max("sensor.ENERGY.Total") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" > now() - interval '1d' GROUP BY 1 ORDER BY 1 ASC) sub2 on COALESCE(sub0.time, sub1.time) = sub2.time